        const price = HYP_REACT_VIP_PRICE[cleanTier] || 0;
        const starlightCost = HYP_REACT_VIP_STARLIGHT[cleanTier] || 0;
        const money = hypnosisNumber(system["持有零花钱"], 0);
        const starlight = hypnosisNumber(system["星光点"], 0);
