        '<button type="button" class="' + (section === "role" ? "active" : "") + '" data-encounter-action="edit-section" data-section="role">角色</button>' +
      '</nav>' +
      (section === "role" ? renderEncounterEditRole(page, draft) : renderEncounterEditPackage(draft)) +
    '</section>';
